export const getUploadSampleUrl = (id: string,) => {




  return `/api/kits/${id}/samples`
}

/**
 * Multipart form. The uploader must accept the Sample Contributor License (licenseAccepted = "true").
 * @summary Upload one sample (WAV/MP3/FLAC/OGG, max 10 MB) into a kit
 */
export const uploadSample = async (id: string,
    sampleUpload: SampleUpload, options?: Parameters<typeof customFetch>[1]): Promise<Sample> => {
    const formData = new FormData();
formData.append(`file`, sampleUpload.file);
formData.append(`instrument`, sampleUpload.instrument);
formData.append(`band`, sampleUpload.band);
formData.append(`licenseAccepted`, sampleUpload.licenseAccepted);

  return customFetch<Sample>(getUploadSampleUrl(id),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





